// ==================== 紫雀社交平台 v16.0 - 全优化版 ====================
(function () {
  "use strict";

  const ID = "ps";
const VERSION = "16.0";

// ═══ 自适应读取当前玩家名 ═══
function getPlayerKey() {
  try {
    const w = window.top || window;
    const ctx = w.SillyTavern?.getContext?.() || w.getContext?.();
    return ctx?.name1 || "";
  } catch { return ""; }
}


  // ═══════════════════════════════════════════════════════════════
  //  工具: XSS转义
  // ═══════════════════════════════════════════════════════════════
  function escapeHtml(str) {
    if (!str && str !== 0) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  // ═══════════════════════════════════════════════════════════════
  //  工具: 公共模板
  // ═══════════════════════════════════════════════════════════════
  function emptyState(icon, title, subtitle) {
    return `<div class="ps-empty"><div class="ps-empty-icon">${icon}</div><div class="ps-empty-title">${escapeHtml(title)}</div>${subtitle ? `<div style="font-size:11px;opacity:.7">${escapeHtml(subtitle)}</div>` : ""}</div>`;
  }

  function errorState(msg) {
    return `<div class="ps-empty"><div class="ps-empty-icon">❌</div><div class="ps-empty-title">加载出错</div><div class="ps-err-detail">${escapeHtml(msg)}</div></div>`;
  }

  function loadingState(text) {
    return `<div class="ps-loading"><span class="ps-spinner"></span><div style="margin-top:10px">${escapeHtml(text || "加载中...")}</div></div>`;
  }

  // ═══════════════════════════════════════════════════════════════
  //  模块1: Storage - 统一持久化层
  // ═══════════════════════════════════════════════════════════════
  const Storage = (() => {
    const PREFIX = "ps-";

    function get(key, fallback = null) {
      try {
        const raw = localStorage.getItem(PREFIX + key);
        return raw ? JSON.parse(raw) : fallback;
      } catch {
        return fallback;
      }
    }

    function set(key, value) {
      try {
        localStorage.setItem(PREFIX + key, JSON.stringify(value));
        return true;
      } catch (e) {
        if (e.name === "QuotaExceededError") {
          cleanOldChats();
          try {
            localStorage.setItem(PREFIX + key, JSON.stringify(value));
            return true;
          } catch {
            return false;
          }
        }
        return false;
      }
    }

    function remove(key) {
      try { localStorage.removeItem(PREFIX + key); } catch {}
    }

    function getRaw(key) {
      try { return localStorage.getItem(PREFIX + key); } catch { return null; }
    }

    function setRaw(key, value) {
      try { localStorage.setItem(PREFIX + key, value); } catch {}
    }

    function cleanOldChats() {
      try {
        const chatKeys = [];
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k?.startsWith(PREFIX + "c-")) chatKeys.push(k);
        }
        chatKeys.slice(0, -10).forEach((k) => localStorage.removeItem(k));
      } catch {}
    }

    return { get, set, remove, getRaw, setRaw };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  模块2: Store - 响应式状态管理
  // ═══════════════════════════════════════════════════════════════
  const Store = (() => {
    const listeners = [];

    const state = {
      config: {
        apiUrl: "", apiKey: "", model: "", playerName: "玩家",
        wallpaper: "", colorScheme: "dark",
        widgets: ["tasks", "contacts", "location", "coser", "bag"],
      },
      resolution: "phone",
      app: "home",
      appHistory: [],
      forum: { cat: "sfw", posts: { sfw: [], nsfw: [] } },
      shop: { cat: "normal", items: { normal: [], special: [] } },
      task: { cat: "normal", list: { normal: [], special: [] } },
      loading: false,
      chat: null,
      gs: null,
      themeStatus: {},
      transitioning: false,
    };

    function get(path) {
      if (!path) return state;
      return path.split(".").reduce((o, k) => o?.[k], state);
    }

    function set(path, value) {
      const keys = path.split(".");
      let obj = state;
      for (let i = 0; i < keys.length - 1; i++) {
        if (!obj[keys[i]] || typeof obj[keys[i]] !== "object") obj[keys[i]] = {};
        obj = obj[keys[i]];
      }
      const oldValue = obj[keys[keys.length - 1]];
      obj[keys[keys.length - 1]] = value;
      emit(path, value, oldValue);
    }

    function emit(path, newVal, oldVal) {
      listeners.forEach(({ pattern, callback }) => {
        if (path === pattern || path.startsWith(pattern + ".") || pattern.startsWith(path + ".")) {
          try { callback(path, newVal, oldVal); } catch (e) { console.error("[PS-Store]", e); }
        }
      });
    }

    function watch(pattern, callback) {
      const entry = { pattern, callback };
      listeners.push(entry);
      return () => {
        const idx = listeners.indexOf(entry);
        if (idx >= 0) listeners.splice(idx, 1);
      };
    }

    function loadConfig() {
      const saved = Storage.get("cfg", {});
      Object.assign(state.config, saved);
      if (!state.config.widgets) state.config.widgets = ["tasks", "contacts", "location"];
      state.resolution = Storage.getRaw("res") || "phone";
      if (!RES_PRESETS[state.resolution]) state.resolution = "phone";
    }

    function saveConfig() { Storage.set("cfg", state.config); }

    return { state, get, set, watch, loadConfig, saveConfig };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  模块3: Notify - 通知系统
  // ═══════════════════════════════════════════════════════════════
  const Notify = (() => {
    let list = [];
    let unread = 0;

    function init() {
      list = Storage.get("notify", []).slice(0, 50);
      unread = parseInt(Storage.getRaw("notify-unread") || "0");
    }

    function add(icon, text) {
      const item = {
        id: Date.now(), icon, text,
        time: new Date().toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" }),
        read: false,
      };
      list.unshift(item);
      if (list.length > 50) list.pop();
      unread++;
      Storage.set("notify", list);
      Storage.setRaw("notify-unread", String(unread));
      updateBadge();
    }

    function markAllRead() {
      list.forEach((n) => (n.read = true));
      unread = 0;
      Storage.set("notify", list);
      Storage.setRaw("notify-unread", "0");
      updateBadge();
    }

    function clear() {
      list = []; unread = 0;
      Storage.remove("notify"); Storage.remove("notify-unread");
      updateBadge();
    }

    function updateBadge() {
      try {
        const d = (window.top || window).document;
        const badge = d.getElementById(`${ID}-notify-badge`);
        if (badge) {
          badge.textContent = unread > 9 ? "9+" : unread;
          badge.style.display = unread > 0 ? "flex" : "none";
        }
      } catch {}
    }

    return {
      init, add, markAllRead, clear, updateBadge,
      get list() { return list; },
      get unread() { return unread; },
    };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  模块4: TGT - 世界书/主题管理
  // ═══════════════════════════════════════════════════════════════
  const TGT = (() => {
    const THEME_MAP = {
      "明日方舟cos主题": "TGT_明日方舟cos主题",
      "碧蓝航线主题": "TGT_碧蓝航线主题",
      "nikkie主题": "TGT_nikkie主题",
      "米哈游游戏主题": "TGT_米哈游游戏主题",
      "自定义游戏主题": "TGT_自定义游戏主题",
    };
    const THEME_NAMES = Object.keys(THEME_MAP);
    const ALWAYS_ENABLED = "TGT_总览";
    let worldBookName = null;

    async function initWorldbook() {
      if (!worldBookName) {
        try {
          const names = getCharWorldbookNames("current");
          worldBookName = names?.primary;
          if (!worldBookName) console.log("[PS-TGT] 警告: 未找到世界书");
        } catch (e) { console.log("[PS-TGT] 世界书初始化失败:", e); }
      }
      return worldBookName;
    }

    async function setEntry(entryName, enabled) {
      if (!worldBookName) await initWorldbook();
      if (!worldBookName || !entryName) return false;
      try {
        let found = false;
        await updateWorldbookWith(worldBookName, (wb) =>
          wb.map((entry) => {
            if (entry.name === entryName) { found = true; return { ...entry, enabled }; }
            return entry;
          })
        );
        return found;
      } catch (e) { console.log("[PS-TGT] 设置条目失败:", entryName, e); return false; }
    }

    async function getEntryStatus(entryName) {
      if (!worldBookName) await initWorldbook();
      if (!worldBookName) return null;
      try {
        let status = null;
        await updateWorldbookWith(worldBookName, (wb) => {
          for (const entry of wb) { if (entry.name === entryName) { status = entry.enabled; break; } }
          return wb;
        });
        return status;
      } catch { return null; }
    }

    return {
      THEME_MAP, THEME_NAMES, ALWAYS_ENABLED,
      initWorldbook, setEntry, getEntryStatus,
      get worldBookName() { return worldBookName; },
    };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  模块5: GameState - 游戏状态桥接
  // ═══════════════════════════════════════════════════════════════
  const GameState = (() => {
    function getMvuData() {
      try {
        const win = window.top || window;
        if (typeof win.Mvu === "undefined" && win.parent?.Mvu) win.Mvu = win.parent.Mvu;
        const data = win.Mvu?.getMvuData({ type: "message", message_id: "latest" })?.stat_data;
        if (data) return data;
        if (win.stat_data) return win.stat_data;
        const ctx = win.SillyTavern?.getContext?.() || win.getContext?.();
        if (ctx?.extensionVariables?.stat_data) return ctx.extensionVariables.stat_data;
        if (ctx?.chat_metadata?.variables?.stat_data) return ctx.chat_metadata.variables.stat_data;
        return null;
      } catch { return null; }
    }

    function get() {
  const data = getMvuData();
  if (data) {
    const pk = getPlayerKey();
    if (data[pk] && !data.主角) data.主角 = data[pk];
    Store.state.gs = data;
    return data;
  }
  if (!Store.state.gs) {
    Store.state.gs = {
      系统: { 当前日期: "第1天", 当前时间: "09:00", 当前地点: "银河会展中心-东入口大厅" },
      主角: { 金钱: 500, 信用: { 好评次数: 0, 差评次数: 0 }, 状态: { 体力: 100 }, 物品栏: {} },
      联系人: {},
      遭遇记录: { 已遭遇coser: [], 接触过的商人: [] },
      任务: { 编号计数器: 100, 进行中任务: {}, 已完成任务: [] },
      Coser列表: {},
    };
  }
  return Store.state.gs;
}


    function setPath(path, value) {
      try {
        const win = window.top || window;
        const gs = get();
        const keys = path.split(".");
        let obj = gs;
        for (let i = 0; i < keys.length - 1; i++) {
          if (!obj[keys[i]]) obj[keys[i]] = {};
          obj = obj[keys[i]];
        }
        obj[keys[keys.length - 1]] = value;
        if (win.Mvu?.setMvuData) { win.Mvu.setMvuData({ type: "message", message_id: "latest", stat_data: gs }); return true; }
        const ctx = win.SillyTavern?.getContext?.() || win.getContext?.();
        if (ctx?.extensionVariables) { ctx.extensionVariables.stat_data = gs; return true; }
        if (ctx?.chat_metadata?.variables) { ctx.chat_metadata.variables.stat_data = gs; return true; }
        if (win.stat_data) { win.stat_data = gs; return true; }
        return false;
      } catch { return false; }
    }

    return { get, setPath, getMvuData };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  模块6: API - 网络请求层（防抖/超时/去重）
  // ═══════════════════════════════════════════════════════════════
  const API = (() => {
    const pending = new Map();
    const TIMEOUT = 30000;

    async function request(prompt, maxTokens = 2000, dedupeKey = null) {
      const c = Store.state.config;
      if (!c.apiUrl || !c.apiKey || !c.model) throw new Error("请先在设置中配置API地址、密钥和模型");
      if (dedupeKey && pending.has(dedupeKey)) return pending.get(dedupeKey);

      let url = c.apiUrl.trim();
      if (!url.endsWith("/")) url += "/";
      if (!url.includes("/chat/completions")) url += (url.endsWith("v1/") ? "" : "v1/") + "chat/completions";

      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), TIMEOUT);

      const promise = (async () => {
        try {
          const res = await fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json", Authorization: `Bearer ${c.apiKey}` },
            body: JSON.stringify({ model: c.model, messages: [{ role: "user", content: prompt }], temperature: 0.9, max_tokens: maxTokens }),
            signal: controller.signal,
          });
          if (!res.ok) {
            let errMsg = `API错误: ${res.status}`;
            try { const ed = await res.json(); if (ed.error?.message) errMsg += ` - ${ed.error.message}`; } catch {}
            throw new Error(errMsg);
          }
          const data = await res.json();
          const content = data.choices?.[0]?.message?.content;
          if (!content) throw new Error("API返回内容为空");
          return content;
        } catch (e) {
          if (e.name === "AbortError") throw new Error("请求超时，请重试");
          if (e.message?.includes("fetch")) throw new Error("网络连接失败，请检查API地址");
          throw e;
        } finally {
          clearTimeout(timer);
          if (dedupeKey) pending.delete(dedupeKey);
        }
      })();

      if (dedupeKey) pending.set(dedupeKey, promise);
      return promise;
    }

    async function fetchModels(url, key) {
      let u = url.replace(/\/$/, "");
      if (!u.endsWith("/v1")) u += "/v1";
      u += "/models";
      const r = await fetch(u, { headers: key ? { Authorization: `Bearer ${key}` } : {} });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const data = await r.json();
      return data.data ? data.data.map((m) => m.id).sort() : [];
    }

    return { request, fetchModels };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  模块7: Router - 页面路由
  // ═══════════════════════════════════════════════════════════════
  const Router = (() => {
    let current = "home";
    const history = [];
    const hooks = {};
    let doc = null;

    function init(d) { doc = d; }
    function register(name, onEnter) { hooks[name] = onEnter; }

    function navigate(page, opts = {}) {
      if (!doc) return;
      if (Store.state.transitioning) return;
      if (current === page && !opts.force) return;
      if (page === "recruit") { Pages.openRecruitPopup(doc); return; }
      if (current !== "home" && !opts.replace) history.push(current);
      Store.set("transitioning", true);
      const currentPage = doc.querySelector(".ps-page.on");
      const targetPage = doc.getElementById(`${ID}-${page}`);
      if (!targetPage) { Store.set("transitioning", false); return; }
      if (currentPage) {
        currentPage.classList.remove("on");
        currentPage.classList.add("slide-out-left");
        setTimeout(() => { currentPage.classList.remove("slide-out-left"); Store.set("transitioning", false); }, 250);
      } else {
        setTimeout(() => Store.set("transitioning", false), 250);
      }
      targetPage.classList.add("on");
      current = page;
      if (hooks[page]) { try { hooks[page](doc); } catch (e) { console.error("[PS-Router]", e); } }
      doc.querySelectorAll(".ps-nav-item").forEach((n) => {
        n.classList.toggle("on", n.dataset.nav === page || (n.dataset.nav === "home" && page === "home"));
      });
    }

    function back() {
      if (history.length) { const prev = history.pop(); navigate(prev, { replace: true }); }
      else goHome();
    }

    function goHome() {
      if (!doc || Store.state.transitioning) return;
      UI.updateHome(doc);
      Store.set("transitioning", true);
      const currentPage = doc.querySelector(".ps-page.on");
      if (currentPage) {
        currentPage.classList.remove("on");
        currentPage.classList.add("slide-out-left");
        setTimeout(() => { currentPage.classList.remove("slide-out-left"); Store.set("transitioning", false); }, 250);
      } else { setTimeout(() => Store.set("transitioning", false), 250); }
      doc.getElementById(`${ID}-home`).classList.add("on");
      current = "home";
      history.length = 0;
      doc.querySelectorAll(".ps-nav-item").forEach((n) => n.classList.toggle("on", n.dataset.nav === "home"));
    }

    function closePhone() {
      if (!doc) return;
      const overlay = doc.getElementById(`${ID}-overlay`);
      if (overlay) overlay.classList.remove("show");
    }

    return {
      init, register, navigate, back, goHome, closePhone,
      get current() { return current; },
      get history() { return history; },
    };
  })();

  // ═══════════════════════════════════════════════════════════════
  //  常量
  // ═══════════════════════════════════════════════════════════════
  const RES_PRESETS = {
    phone: { label: "📱", name: "手机", width: 380, height: 560, radius: 36, shadow: 10 },
    tablet: { label: "📋", name: "平板", width: 480, height: 760, radius: 28, shadow: 8 },
    pc: { label: "💻", name: "电脑", width: 400, height: 760, radius: 16, shadow: 6 },
  };
  const RES_ORDER = ["phone", "tablet", "pc"];

  const VENUES = {
    "银河会展中心": { icon: "🏛️", desc: "五万平方米大型展馆", areas: {
      "一楼": ["东入口大厅", "中央展区", "主舞台", "餐饮区"],
      "二楼": ["同人贩售区", "摄影区", "coser休息室", "更衣室"],
      "三楼": ["VIP区域", "嘉宾休息室"],
      "隐蔽区域": ["货运通道暗角", "消防楼梯间", "杂物间"],
    }},
    "幻梦同人馆": { icon: "🎨", desc: "旧纺织厂改造", areas: {
      "一楼": ["入口区", "主展区", "小舞台", "饮品吧台"],
      "二楼": ["画师专区", "交流区", "更衣间"],
      "隐蔽区域": ["旧厂房角落", "杂物间"],
    }},
    "星光动漫中心": { icon: "⭐", desc: "钢结构玻璃幕墙", areas: {
      "一楼": ["入口大厅", "周边贩售区", "VR体验区", "活动舞台"],
      "二楼": ["同人贩售区", "coser休息区", "摄影区"],
      "三楼": ["天台露台"],
      "隐蔽区域": ["地下停车场", "设备间", "天台角落"],
    }},
  };

  const TYPE_ICONS = {
    "同人志":"📚","同人本":"📚","本子":"📕","R18":"📕","徽章":"🎀","手办":"🎎",
    "周边":"🎁","食物":"🍙","饮料":"🥤","道具":"🔧","服装":"👗","饰品":"💍",
    "票券":"🎫","照片":"📷","私房":"🔒","特殊":"⭐","海报":"🖼️","挂件":"🔮",
    "钥匙扣":"🔑","抱枕":"🛏️","光盘":"💿","卡牌":"🃏","画集":"🎨","模型":"🤖",
    "武器":"⚔️","药品":"💊","工具":"🛠️","信件":"✉️","随身物品":"📱","成人用品":"🔞","其他":"📦",
  };

  const PALETTE = ["#FF6B6B","#4ECDC4","#45B7D1","#96CEB4","#FFEAA7","#DDA0DD","#98D8C8","#F7DC6F","#BB8FCE","#85C1E9"];

  // ═══════════════════════════════════════════════════════════════
  //  工具函数
  // ═══════════════════════════════════════════════════════════════
  let _mobileCache = null;
  function isMobile() {
    if (_mobileCache !== null) return _mobileCache;
    const w = window.top || window;
    _mobileCache = w.innerWidth <= 1024 || /iPhone|iPad|iPod|Android|Mobile/i.test(navigator.userAgent);
    return _mobileCache;
  }
  function refreshMobileCache() { _mobileCache = null; }

  function calculateOptimalScale() {
    const w = window.top || window;
    const preset = RES_PRESETS[Store.state.resolution] || RES_PRESETS.phone;
    if (isMobile()) {
      const scaleW = (w.innerWidth - 40) / preset.width;
      const scaleH = (w.innerHeight - 120) / preset.height;
      return Math.max(0.5, Math.min(0.95, Math.min(scaleW, scaleH)));
    }
    return 1.0;
  }

  function getBagIcon(type, name) {
    const combined = type + name;
    for (const [key, icon] of Object.entries(TYPE_ICONS)) { if (combined.includes(key)) return icon; }
    return "📦";
  }

  function parseBagItems(gs) {
    let rawBag = gs.主角?.物品栏;
    let items = [];
    if (rawBag && typeof rawBag === "object" && !Array.isArray(rawBag)) {
      items = Object.entries(rawBag)
        .filter(([name, item]) => name && name !== "undefined" && name !== "null" && item && typeof item === "object")
        .map(([name, item]) => ({
          name: String(name),
          type: String(item.类型 || item.type || "其他"),
          desc: String(item.描述 || item.desc || item.description || "无描述"),
          count: Math.max(1, parseInt(item.数量 || item.count || item.quantity || 1) || 1),
        }));
    } else if (Array.isArray(rawBag)) {
      items = rawBag.filter((item) => item && typeof item === "object").map((item, i) => ({
        name: String(item.名称 || item.name || item.物品名 || `物品${i + 1}`),
        type: String(item.类型 || item.type || "其他"),
        desc: String(item.描述 || item.desc || "无描述"),
        count: Math.max(1, parseInt(item.数量 || item.count || 1) || 1),
      }));
    }
    return items.filter((item) => item.count > 0);
  }

  function sendMsg(msg) {
    try {
      const w = window.top || window;
      const ta = w.document.getElementById("send_textarea");
      if (ta) {
        ta.value = msg;
        ta.dispatchEvent(new Event("input", { bubbles: true }));
        const sendBtn = w.document.getElementById("send_but");
        if (sendBtn) sendBtn.click();
      }
    } catch {}
  }

  function setupLongPress(el, callback, duration = 500) {
    let timer = null, startX, startY, triggered = false;
    const start = (x, y) => {
      startX = x; startY = y; triggered = false;
      timer = setTimeout(() => { triggered = true; callback(x, y); }, duration);
    };
    const cancel = () => { if (timer) { clearTimeout(timer); timer = null; } };
    el.addEventListener("pointerdown", (e) => start(e.clientX, e.clientY));
    el.addEventListener("pointermove", (e) => {
      if (Math.abs(e.clientX - startX) > 10 || Math.abs(e.clientY - startY) > 10) cancel();
    });
    el.addEventListener("pointerup", () => cancel());
    el.addEventListener("pointercancel", () => cancel());
    el.addEventListener("click", (e) => {
      if (triggered) { e.preventDefault(); e.stopPropagation(); triggered = false; }
    }, true);
  }

  function showLongPressMenu(d, x, y, items) {
    d.querySelectorAll(".ps-longpress-menu").forEach((e) => e.remove());
    const menu = document.createElement("div");
    menu.className = "ps-longpress-menu";
    const vw = (window.top || window).innerWidth;
    const vh = (window.top || window).innerHeight;
    menu.innerHTML = items.map((it) =>
      `<div class="ps-lp-item${it.danger ? " danger" : ""}" data-action="${it.action}">${it.icon} ${escapeHtml(it.label)}</div>`
    ).join("");
    menu.style.left = x + "px";
    menu.style.top = y + "px";
    d.body.appendChild(menu);
    const rect = menu.getBoundingClientRect();
    if (rect.right > vw - 10) menu.style.left = (vw - rect.width - 10) + "px";
    if (rect.bottom > vh - 10) menu.style.top = (vh - rect.height - 10) + "px";
    if (rect.left < 10) menu.style.left = "10px";
    if (rect.top < 10) menu.style.top = "10px";
    requestAnimationFrame(() => menu.classList.add("show"));
    const close = () => {
      menu.classList.remove("show");
      setTimeout(() => menu.remove(), 200);
      d.removeEventListener("pointerdown", outsideHandler);
    };
    const outsideHandler = (e) => { if (!menu.contains(e.target)) close(); };
    setTimeout(() => d.addEventListener("pointerdown", outsideHandler), 10);
    return new Promise((resolve) => {
      menu.querySelectorAll(".ps-lp-item").forEach((el) => {
        el.onclick = () => { close(); resolve(el.dataset.action); };
      });
    });
  }

  function showConfirm(d, title, desc, onConfirm) {
    d.querySelectorAll(".ps-confirm").forEach((e) => e.remove());
    const overlay = document.createElement("div");
    overlay.className = "ps-confirm";
    overlay.innerHTML = `<div class="ps-confirm-box"><div class="ps-confirm-title">${escapeHtml(title)}</div><div class="ps-confirm-desc">${escapeHtml(desc).replace(/\n/g, "<br>")}</div><div class="ps-confirm-btns"><button class="ps-confirm-btn no">取消</button><button class="ps-confirm-btn yes">确定</button></div></div>`;
    overlay.querySelector(".ps-confirm-btn.no").onclick = () => overlay.remove();
    overlay.querySelector(".ps-confirm-btn.yes").onclick = () => { overlay.remove(); if (onConfirm) onConfirm(); };
    overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };
    d.body.appendChild(overlay);
  }

  function toast(d, msg, type = "") {
    try {
      const t = d.getElementById(`${ID}-toast`);
      if (!t) return;
      t.textContent = msg;
      t.className = `ps-toast ${type} show`;
      clearTimeout(t._timer);
      t._timer = setTimeout(() => t.classList.remove("show"), 3000);
    } catch {}
  }

  function initPullToRefresh(container, onRefresh) {
    let startY = 0, pulling = false, indicator = null;
    container.addEventListener("touchstart", (e) => {
      if (container.scrollTop <= 0 && e.touches.length === 1) { startY = e.touches[0].clientY; pulling = true; }
    }, { passive: true });
    container.addEventListener("touchmove", (e) => {
      if (!pulling) return;
      const dy = e.touches[0].clientY - startY;
      if (dy > 10 && container.scrollTop <= 0) {
        if (!indicator) {
          indicator = document.createElement("div");
          indicator.className = "ps-pull-indicator";
          indicator.innerHTML = '<span class="ps-spinner"></span> 下拉刷新';
          container.parentElement.insertBefore(indicator, container);
        }
        indicator.style.height = Math.min(dy * 0.5, 50) + "px";
        indicator.style.opacity = Math.min(dy / 80, 1);
        if (dy > 80) indicator.innerHTML = '<span class="ps-spinner"></span> 释放刷新';
      }
    }, { passive: true });
    container.addEventListener("touchend", () => {
      if (!pulling) return;
      pulling = false;
      if (indicator) {
        const dy = parseInt(indicator.style.height) || 0;
        if (dy >= 40) {
          indicator.innerHTML = '<span class="ps-spinner"></span> 刷新中...';
          indicator.style.height = "40px";
          onRefresh().finally(() => { if (indicator) { indicator.remove(); indicator = null; } });
        } else { indicator.remove(); indicator = null; }
      }
    });
  }

  // ── 增量DOM更新工具 ──
  function patchList(container, items, keyFn, renderFn, afterPatch) {
    const existingMap = new Map();
    container.querySelectorAll("[data-key]").forEach((el) => {
      existingMap.set(el.dataset.key, el);
    });
    const newKeys = new Set();
    const fragment = document.createDocumentFragment();
    items.forEach((item) => {
      const key = keyFn(item);
      newKeys.add(key);
      if (existingMap.has(key)) {
        fragment.appendChild(existingMap.get(key));
      } else {
        const wrapper = document.createElement("div");
        wrapper.innerHTML = renderFn(item);
        const newEl = wrapper.firstElementChild;
        if (newEl) { newEl.dataset.key = key; fragment.appendChild(newEl); }
      }
    });
    existingMap.forEach((el, key) => { if (!newKeys.has(key)) el.remove(); });
    container.innerHTML = "";
    container.appendChild(fragment);
    if (afterPatch) afterPatch(container);
  }

