  //  模块8: UI - 界面管理
  // ═══════════════════════════════════════════════════════════════
  const UI = (() => {
    function applyContainerStyles(d) {
      const phone = d.getElementById(`${ID}-phone`);
      const overlay = d.getElementById(`${ID}-overlay`);
      if (!phone || !overlay) return;
      const scale = calculateOptimalScale();
      const w = (window.top || window).innerWidth;
      const h = (window.top || window).innerHeight;
      const preset = RES_PRESETS[Store.state.resolution] || RES_PRESETS.phone;
      phone.style.width = preset.width + "px";
      phone.style.height = preset.height + "px";
      phone.style.position = "fixed";
      phone.style.zIndex = "2147483645";
      overlay.style.position = "fixed";
      overlay.style.inset = "0";
      overlay.style.zIndex = "2147483644";
      phone.style.transformOrigin = "0 0";
      phone.style.transform = `scale(${scale})`;
      const saved = !isMobile() ? Storage.getRaw("phone-pos") : null;
      if (saved) {
        try {
          const p = JSON.parse(saved);
          phone.style.left = Math.max(0, p.x) + "px";
          phone.style.top = Math.max(50, p.y) + "px";
        } catch { forceCenter(phone, w, h, preset.width, preset.height, scale); }
      } else {
        forceCenter(phone, w, h, preset.width, preset.height, scale);
      }
      const keepClasses = [];
      if (phone.classList.contains("has-wp")) keepClasses.push("has-wp");
      if (phone.classList.contains("light-theme")) keepClasses.push("light-theme");
      phone.className = `res-${Store.state.resolution} ${keepClasses.join(" ")}`.trim();
      phone.style.borderRadius = preset.radius + "px";
      phone.style.boxShadow = `0 0 0 ${preset.shadow}px #1a1a2e, 0 30px 60px rgba(0,0,0,.5)`;
      const resBtn = d.getElementById(`${ID}-res-btn`);
      if (resBtn) { resBtn.textContent = preset.label; resBtn.title = `当前：${preset.name}`; }
    }

    function forceCenter(phone, winW, winH, phoneW, phoneH, scale) {
      const actualW = phoneW * scale;
      const actualH = phoneH * scale;
      phone.style.left = Math.max(0, (winW - actualW) / 2) + "px";
      phone.style.top = Math.max(50, (winH - actualH) / 2) + "px";
    }

    function cycleResolution(d) {
      const idx = RES_ORDER.indexOf(Store.state.resolution);
      Store.set("resolution", RES_ORDER[(idx + 1) % RES_ORDER.length]);
      Storage.remove("phone-pos");
      Storage.setRaw("res", Store.state.resolution);
      applyContainerStyles(d);
      toast(d, `切换至${RES_PRESETS[Store.state.resolution].name}模式`, "ok");
    }

    function applyColorScheme(d) {
      const phone = d.getElementById(`${ID}-phone`);
      if (!phone) return;
      phone.classList.toggle("light-theme", Store.state.config.colorScheme === "light");
    }

    function applyWallpaper(d) {
      const phone = d.getElementById(`${ID}-phone`);
      if (!phone) return;
      if (Store.state.config.wallpaper) {
        phone.style.backgroundImage = `url(${Store.state.config.wallpaper})`;
        phone.classList.add("has-wp");
      } else {
        phone.style.backgroundImage = "";
        phone.classList.remove("has-wp");
      }
    }

    function updateHome(d) {
      try {
        const gs = GameState.get();
        d.getElementById(`${ID}-money`).textContent = gs.主角?.金钱 ?? "--";
        d.getElementById(`${ID}-hp`).textContent = gs.主角?.状态?.体力 ?? "--";
        d.getElementById(`${ID}-credit`).textContent = gs.主角?.信用?.好评次数 ?? "--";
        d.getElementById(`${ID}-cnt`).textContent = Object.keys(gs.联系人 || {}).length;
        d.getElementById(`${ID}-time`).textContent = gs.系统?.当前时间 || "--:--";
        d.getElementById(`${ID}-date`).textContent = gs.系统?.当前日期 || "--";
        d.getElementById(`${ID}-loc`).textContent = gs.系统?.当前地点 || "--";
        const bal = d.getElementById(`${ID}-bal`);
        if (bal) bal.textContent = gs.主角?.金钱 ?? "--";
        Pages.renderWidgets(d);
        Notify.updateBadge();
      } catch {}
    }

    function initBtnDrag(btn, d) {
      let isMoving = false, hasMoved = false, startX, startY, initialLeft, initialTop;
      const openPanel = () => {
        updateHome(d);
        applyContainerStyles(d);
        d.getElementById(`${ID}-overlay`).classList.add("show");
      };
      btn.onpointerdown = (e) => {
        if (e.pointerType === "mouse" && e.button !== 0) return;
        isMoving = true; hasMoved = false;
        startX = e.clientX; startY = e.clientY;
        const r = btn.getBoundingClientRect();
        initialLeft = r.left; initialTop = r.top;
        btn.setPointerCapture(e.pointerId);
        btn.classList.add("dragging");
      };
      btn.onpointermove = (e) => {
        if (!isMoving) return;
        const dx = e.clientX - startX, dy = e.clientY - startY;
        if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
          hasMoved = true;
          const w = (window.top || window).innerWidth, h = (window.top || window).innerHeight;
          btn.style.left = Math.max(0, Math.min(initialLeft + dx, w - btn.offsetWidth)) + "px";
          btn.style.top = Math.max(0, Math.min(initialTop + dy, h - btn.offsetHeight)) + "px";
          btn.style.right = "auto"; btn.style.bottom = "auto";
        }
      };
      btn.onpointerup = (e) => {
        if (!isMoving) return;
        isMoving = false;
        btn.classList.remove("dragging");
        btn.releasePointerCapture(e.pointerId);
        if (!hasMoved) openPanel();
        else Storage.set("pos", { x: btn.getBoundingClientRect().left, y: btn.getBoundingClientRect().top });
      };
      btn.onpointercancel = () => { isMoving = false; btn.classList.remove("dragging"); };
    }

    function initPhoneDrag(d) {
      const phone = d.getElementById(`${ID}-phone`);
      const topBar = d.getElementById(`${ID}-drag-bar`);
      const bottomNav = phone ? phone.querySelector(".ps-nav") : null;
      if (!phone || !topBar) return;
      let isDragging = false, hasDragMoved = false, startX, startY, initialLeft, initialTop;

      function isInteractive(target) {
        if (target.tagName === "BUTTON" || target.tagName === "INPUT" || target.tagName === "SELECT") return true;
        return !!(target.closest("button") || target.closest(".ps-close-btn") || target.closest(".ps-res-btn") || target.closest(".ps-nav-item") || target.closest(".ps-notify-wrap"));
      }

      const startDrag = (e) => {
        if (isInteractive(e.target)) return;
        isDragging = true; hasDragMoved = false;
        startX = e.clientX; startY = e.clientY;
        initialLeft = parseInt(phone.style.left) || 0;
        initialTop = parseInt(phone.style.top) || 0;
        phone.setPointerCapture(e.pointerId);
        phone.classList.add("phone-dragging");
        topBar.classList.add("bar-dragging");
      };
      const onMove = (e) => {
        if (!isDragging) return;
        const dx = e.clientX - startX, dy = e.clientY - startY;
        if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
          hasDragMoved = true;
          phone.style.left = (initialLeft + dx) + "px";
          phone.style.top = (initialTop + dy) + "px";
        }
      };
      const endDrag = (e) => {
        if (!isDragging) return;
        isDragging = false;
        phone.classList.remove("phone-dragging");
        topBar.classList.remove("bar-dragging");
        try { phone.releasePointerCapture(e.pointerId); } catch {}
        if (hasDragMoved && !isMobile()) {
          Storage.set("phone-pos", { x: parseInt(phone.style.left) || 0, y: parseInt(phone.style.top) || 0 });
        }
      };
      const cancelDrag = () => { isDragging = false; phone.classList.remove("phone-dragging"); topBar.classList.remove("bar-dragging"); };

      topBar.addEventListener("pointerdown", startDrag);
      if (bottomNav) bottomNav.addEventListener("pointerdown", startDrag);
      phone.addEventListener("pointermove", onMove);
      phone.addEventListener("pointerup", endDrag);
      phone.addEventListener("pointercancel", cancelDrag);

      if (!isMobile()) {
        const hint = d.getElementById(`${ID}-drag-hint`);
        try {
          if (hint && !Storage.getRaw("hint-shown")) {
            setTimeout(() => { hint.classList.add("show"); setTimeout(() => hint.classList.remove("show"), 2000); Storage.setRaw("hint-shown", "1"); }, 800);
          }
        } catch {}
      }
    }

    return { applyContainerStyles, cycleResolution, applyColorScheme, applyWallpaper, updateHome, initBtnDrag, initPhoneDrag };
  })();

