      let h = "";
      if (active.length) {
        h += '<div style="padding:14px 14px 0"><div style="font-size:13px;font-weight:600;color:var(--muted);margin-bottom:10px">📌 进行中</div>';
        active.forEach(([id, t]) => {
          h += `<div class="ps-task"><div class="ps-task-hdr"><div class="ps-task-name">🔥 ${escapeHtml(t.名称 || "未知任务")}</div><div class="ps-task-reward">💰 ${escapeHtml(String(t.奖励 || "?"))}</div></div><div class="ps-task-desc">${escapeHtml(t.介绍 || "")}</div><button class="ps-task-btn" data-done="${escapeHtml(id)}">✅ 完成</button></div>`;
        });
        h += "</div>";
      }
      h += `<div style="padding:14px 14px 0"><div style="font-size:13px;font-weight:600;color:var(--muted);margin-bottom:10px">${cat === "special" ? "⭐ 特殊任务" : "📝 可接取"}</div>`;
      if (!tasks.length) {
        h += emptyState("📭", "暂无可接取任务");
      } else {
        const contacts = gs.联系人 || {};
        const hasSp = Object.values(contacts).some((c) => (c.备注 || "").match(/特殊|R18|私房|夜间|成人/));
        tasks.forEach((t) => {
          const lock = t.isSp && !hasSp;
          h += `<div class="ps-task ${t.isSp ? "sp" : ""} ${lock ? "lock" : ""}"><div class="ps-task-hdr"><div class="ps-task-name">${t.isSp ? "⭐ " : ""}${escapeHtml(t.name)}</div><div class="ps-task-reward">💰 ${t.reward}</div></div><div class="ps-task-desc">${escapeHtml(t.desc)} · 👤${escapeHtml(t.pub)}</div><button class="ps-task-btn" data-tid="${t.id}" ${lock ? "disabled" : ""}>${lock ? "🔒 需特殊联系人" : "接取任务"}</button></div>`;
        });
      }
      h += "</div>";
      const el = d.getElementById(`${ID}-task-list`);
      el.innerHTML = h;
      el.querySelectorAll("[data-tid]").forEach((b) => {
        b.onclick = () => {
          try {
            const t = Store.state.task.list[cat].find((x) => x.id === b.dataset.tid);
            if (!t) { toast(d, "任务不存在", "err"); return; }
            Store.set(`task.list.${cat}`, Store.state.task.list[cat].filter((x) => x.id !== t.id));
            sendMsg(`[系统] 接取了任务「${t.name}」，奖励${t.reward}元`);
            toast(d, "任务接取成功！", "ok");
            Notify.add("📋", `接取任务「${t.name}」奖励${t.reward}💰`);
            renderTask(d, cat);
          } catch (err) { toast(d, `接取任务出错：${err.message}`, "err"); }
        };
      });
      el.querySelectorAll("[data-done]").forEach((b) => {
        b.onclick = () => {
          try {
            const tid = b.dataset.done;
            const t = gs.任务?.进行中任务?.[tid];
            if (!t) { toast(d, "任务数据异常", "err"); return; }
            sendMsg(`[系统] 完成了任务「${t.名称}」`);
            toast(d, "任务完成！", "ok");
            Notify.add("✅", `完成任务「${t.名称}」`);
            renderTask(d, cat);
          } catch (err) { toast(d, `完成任务出错：${err.message}`, "err"); }
        };
      });
    }

