    // ── Coser信息页 ──
    function renderCoserInfo(d) {
      try {
        const gs = GameState.get();
        const coserList = gs.Coser列表 || gs["Coser列表"] || {};
        const entries = Object.entries(coserList);
        const el = d.getElementById(`${ID}-coserinfo-list`);
        const colors = ["#FF6B9D","#6C5CE7","#00B894","#FDCB6E","#E17055","#0984E3","#A29BFE","#55E6C1","#F8A5C2","#778BEB"];
        let headerHtml = `<div class="ps-coser-summary"><div class="ps-coser-summary-title">💃 已遭遇的Coser</div><div class="ps-coser-summary-count">${entries.length} 位Coser</div></div>`;
        if (!entries.length) {
          el.innerHTML = headerHtml + emptyState("💃", "尚未遭遇任何Coser", "去漫展逛逛，遇到的Coser会自动记录");
          return;
        }
        el.innerHTML = headerHtml + '<div class="ps-coser-list" id="' + ID + '-coser-inner"></div>';
        const listContainer = d.getElementById(`${ID}-coser-inner`);
        patchList(listContainer, entries,
          ([cn]) => cn,
          ([cn, coser], idx) => {
            const i = typeof idx === "number" ? idx : entries.findIndex(([c]) => c === cn);
            const name = escapeHtml(coser.姓名 || "未知");
            const cosRole = escapeHtml(coser.cos角色 || coser["cos角色"] || "未知");
            const cosStyle = escapeHtml(coser.cos风格 || coser["cos风格"] || "未知");
            const type = coser.类型 || "普通";
            const favor = Math.max(0, Math.min(100, parseInt(coser.好感度) || 0));
            const location = escapeHtml(coser.当前位置 || "未知");
            const status = escapeHtml(coser.当前状态 || "未知");
            const sexCount = parseInt(coser.性爱次数) || 0;
            let favorColor = "#EF4444";
            if (favor >= 80) favorColor = "#10B981";
            else if (favor >= 60) favorColor = "#3B82F6";
            else if (favor >= 40) favorColor = "#F59E0B";
            else if (favor >= 20) favorColor = "#F97316";
