              <div class="ps-coser-card-hdr">
                <div class="ps-coser-avatar" style="background:${bgColor}">${name[0] || "?"}</div>
                <div class="ps-coser-main">
                  <div class="ps-coser-name">${name} <span class="ps-coser-cn">CN:${escapeHtml(cn)}</span> <span class="ps-coser-type t-${escapeHtml(type)}">${escapeHtml(type)}</span></div>
                  <div class="ps-coser-sub">cos: ${cosRole} · ${cosStyle}</div>
                </div>
                <span class="ps-coser-arrow">▼</span>
              </div>
              <div class="ps-coser-detail">
                <div class="ps-coser-row"><span class="ps-coser-row-label">📍 当前位置</span><span class="ps-coser-row-value">${location}</span></div>
                <div class="ps-coser-row"><span class="ps-coser-row-label">📋 当前状态</span><span class="ps-coser-row-value">${status}</span></div>
                <div class="ps-coser-row"><span class="ps-coser-row-label">🎭 Cos角色</span><span class="ps-coser-row-value">${cosRole}</span></div>
                <div class="ps-coser-row"><span class="ps-coser-row-label">✨ Cos风格</span><span class="ps-coser-row-value">${cosStyle}</span></div>
                <div class="ps-coser-row"><span class="ps-coser-row-label">❤️ 好感度</span><span class="ps-coser-row-value"><div class="ps-coser-favor"><div class="ps-coser-favor-bar"><div class="ps-coser-favor-fill" style="width:${favor}%;background:${favorColor}"></div></div><span class="ps-coser-favor-num" style="color:${favorColor}">${favor}</span></div></span></div>
                <div class="ps-coser-row"><span class="ps-coser-row-label">🔞 亲密次数</span><span class="ps-coser-row-value">${sexCount}</span></div>
              </div>
