    // ── 联系人 ──
    function renderContact(d) {
      try {
        const gs = GameState.get();
        const contacts = gs.联系人 || {};
        const ids = Object.keys(contacts);
        const el = d.getElementById(`${ID}-contact-list`);
        if (!ids.length) {
          el.innerHTML = emptyState("👥", "暂无联系人", "遇到的人会自动添加");
          return;
        }
        const headerHtml = `<div style="padding:10px 14px;font-size:11px;color:var(--muted)">共 ${ids.length} 位联系人 · 长按可操作</div>`;
        el.innerHTML = headerHtml + '<div id="' + ID + '-contact-inner"></div>';
        const listContainer = d.getElementById(`${ID}-contact-inner`);

        const contactItems = ids.map((id, i) => ({ id, contact: contacts[id], index: i }));

        patchList(listContainer, contactItems,
          (item) => item.id,
          (item) => {
            const c = item.contact;
            const name = escapeHtml(c.姓名 || item.id);
            const note = escapeHtml(c.备注 || "无备注");
            return `<div data-key="${escapeHtml(item.id)}"><div class="ps-contact" data-cid="${escapeHtml(item.id)}" data-cname="${name}">
              <div class="ps-contact-avatar" style="background:${PALETTE[item.index % PALETTE.length]}">${name[0] || "?"}</div>
              <div class="ps-contact-info"><div class="ps-contact-name">${name}</div>
              <div class="ps-contact-note" data-note-display="${escapeHtml(item.id)}">${note}</div></div>
              <div class="ps-contact-actions">
                <button class="ps-contact-act chat-act" data-chat-cid="${escapeHtml(item.id)}" title="聊天">💬</button>
                <button class="ps-contact-act edit" data-edit-cid="${escapeHtml(item.id)}" title="编辑备注">✏️</button>
              </div>
            </div>
            <div class="ps-edit-row" id="${ID}-edit-${item.id}" style="display:none">
              <input class="ps-edit-input" id="${ID}-edit-input-${item.id}" value="${note}" placeholder="输入备注...">
              <button class="ps-edit-save" data-save-cid="${escapeHtml(item.id)}">保存</button>
              <button class="ps-edit-cancel" data-cancel-cid="${escapeHtml(item.id)}">取消</button>
            </div></div>`;
          },
          (container) => {
            bindContactEvents(d, container);
          }
        );
      } catch (err) {
        d.getElementById(`${ID}-contact-list`).innerHTML = errorState(err.message);
      }
    }

    function bindContactEvents(d, container) {
      // 聊天按钮
      container.querySelectorAll("[data-chat-cid]").forEach((btn) => {
        btn.onclick = (e) => { e.stopPropagation(); openChat(d, btn.dataset.chatCid); };
      });
      // 编辑按钮
      container.querySelectorAll("[data-edit-cid]").forEach((btn) => {
        btn.onclick = (e) => {
          e.stopPropagation();
          const cid = btn.dataset.editCid;
          const editRow = d.getElementById(`${ID}-edit-${cid}`);
          if (editRow) {
            const isVisible = editRow.style.display !== "none";
            container.querySelectorAll(".ps-edit-row").forEach((r) => (r.style.display = "none"));
            if (!isVisible) {
              editRow.style.display = "flex";
              const input = d.getElementById(`${ID}-edit-input-${cid}`);
              if (input) { input.focus(); input.select(); }
            }
          }
        };
      });
      // 保存备注
      container.querySelectorAll("[data-save-cid]").forEach((btn) => {
        btn.onclick = (e) => {
          e.stopPropagation();
          const cid = btn.dataset.saveCid;
          const input = d.getElementById(`${ID}-edit-input-${cid}`);
          if (!input) return;
          const newNote = input.value.trim();
          try {
            const gs = GameState.get();
            if (gs.联系人?.[cid]) {
              const oldNote = gs.联系人[cid].备注 || "";
              gs.联系人[cid].备注 = newNote;
              GameState.setPath("联系人", gs.联系人);
              sendMsg(`[系统] 修改了联系人「${gs.联系人[cid].姓名}」的备注：从「${oldNote}」改为「${newNote}」`);
              const noteDisplay = d.querySelector(`[data-note-display="${cid}"]`);
              if (noteDisplay) noteDisplay.textContent = newNote || "无备注";
              d.getElementById(`${ID}-edit-${cid}`).style.display = "none";
              toast(d, "备注已更新", "ok");
              Notify.add("✏️", `修改了「${gs.联系人[cid].姓名}」的备注`);
            }
          } catch (err) { toast(d, `修改备注出错：${err.message}`, "err"); }
        };
      });
      // 取消编辑
      container.querySelectorAll("[data-cancel-cid]").forEach((btn) => {
        btn.onclick = (e) => {
          e.stopPropagation();
          const cid = btn.dataset.cancelCid;
          d.getElementById(`${ID}-edit-${cid}`).style.display = "none";
          const gs = GameState.get();
          const input = d.getElementById(`${ID}-edit-input-${cid}`);
          if (input && gs.联系人?.[cid]) input.value = gs.联系人[cid].备注 || "";
        };
      });
      // 回车保存
      container.querySelectorAll(".ps-edit-input").forEach((input) => {
        input.onkeypress = (e) => {
          if (e.key === "Enter") {
            const cid = input.id.replace(`${ID}-edit-input-`, "");
            d.querySelector(`[data-save-cid="${cid}"]`)?.click();
          }
        };
      });
      // 长按菜单
      container.querySelectorAll(".ps-contact[data-cid]").forEach((contactEl) => {
        setupLongPress(contactEl, async (x, y) => {
          const cid = contactEl.dataset.cid;
          const cname = contactEl.dataset.cname;
          const action = await showLongPressMenu(d, x, y, [
            { action: "chat", icon: "💬", label: "发消息" },
            { action: "edit", icon: "✏️", label: "编辑备注" },
            { action: "delete", icon: "🗑️", label: "删除联系人", danger: true },
          ]);
          if (action === "chat") { openChat(d, cid); }
          else if (action === "edit") { d.querySelector(`[data-edit-cid="${cid}"]`)?.click(); }
          else if (action === "delete") {
            showConfirm(d, "删除联系人", `确定要删除「${cname}」吗？\n聊天记录也会被清除。`, () => {
              try {
                const gs = GameState.get();
                if (gs.联系人?.[cid]) {
                  const deletedName = gs.联系人[cid].姓名;
                  delete gs.联系人[cid];
                  GameState.setPath("联系人", gs.联系人);
                  sendMsg(`[系统] 删除了联系人「${deletedName}」`);
                  Storage.remove(`c-${cid}`);
                  toast(d, `已删除「${deletedName}」`, "ok");
                  Notify.add("🗑️", `删除了联系人「${deletedName}」`);
                  renderContact(d);
                  UI.updateHome(d);
                }
              } catch (err) { toast(d, `删除出错：${err.message}`, "err"); }
            });
          }
        });
      });
    }

    // ── 消息列表 ──
    function renderMsgList(d) {
      const gs = GameState.get();
      const contacts = gs.联系人 || {};
      const ids = Object.keys(contacts);
      const el = d.getElementById(`${ID}-msglist-content`);
      if (!ids.length) {
        el.innerHTML = emptyState("💬", "暂无消息", "添加联系人后可以聊天");
        return;
      }
      const sorted = ids.map((id, i) => {
        const msgs = Storage.get(`c-${id}`, []);
        const last = msgs.length ? msgs[msgs.length - 1] : null;
        return { id, contact: contacts[id], msgs, last, color: PALETTE[i % PALETTE.length] };
      }).sort((a, b) => {
        if (b.msgs.length && a.msgs.length) return (b.last?.id || b.msgs.length) - (a.last?.id || a.msgs.length);
        return (b.msgs.length ? 1 : 0) - (a.msgs.length ? 1 : 0);
      });

      const headerHtml = `<div style="padding:10px 14px;font-size:11px;color:var(--muted)">${sorted.length} 个对话</div>`;
      el.innerHTML = headerHtml + '<div id="' + ID + '-msglist-inner"></div>';
      const listContainer = d.getElementById(`${ID}-msglist-inner`);

      patchList(listContainer, sorted,
        (item) => item.id,
        (item) => {
          const name = escapeHtml(item.contact.姓名 || item.id);
          const lastText = escapeHtml(item.last ? (item.last.s ? `我: ${item.last.t}` : item.last.t) : "暂无消息");
          return `<div class="ps-msg-list-item" data-msg-cid="${escapeHtml(item.id)}" data-key="${escapeHtml(item.id)}">
            <div class="ps-msg-list-avatar" style="background:${item.color}">${name[0]}</div>
            <div class="ps-msg-list-info"><div class="ps-msg-list-name">${name}</div>
            <div class="ps-msg-list-last">${lastText}</div></div>
            ${item.msgs.length ? "" : '<div class="ps-msg-list-unread"></div>'}</div>`;
        },
        (container) => {
          container.querySelectorAll("[data-msg-cid]").forEach((msgEl) => {
            msgEl.onclick = () => openChat(d, msgEl.dataset.msgCid);
          });
        }
      );
    }

    // ── 聊天 ──
    function openChat(d, cid) {
      try {
        const gs = GameState.get();
        const c = gs.联系人?.[cid];
        if (!c) { toast(d, "联系人不存在", "err"); return; }
        Store.set("chat", { id: cid, ...c });
        d.querySelectorAll(".ps-page").forEach((p) => p.classList.remove("on"));
        d.getElementById(`${ID}-chat-page`).classList.add("on");
        d.getElementById(`${ID}-chat-name`).textContent = c.姓名 || cid;
        const msgs = Storage.get(`c-${cid}`, []);
        const el = d.getElementById(`${ID}-chat-msgs`);
        el.innerHTML = msgs.length
          ? msgs.map((m) => `<div class="ps-msg ${m.s ? "sent" : "recv"}"><div class="ps-bubble">${escapeHtml(m.t)}</div></div>`).join("")
          : '<div style="text-align:center;color:var(--muted);padding:30px">开始聊天吧~</div>';
        el.scrollTop = el.scrollHeight;
      } catch (err) { toast(d, `打开聊天出错：${err.message}`, "err"); }
    }

    async function sendChat(d) {
      const chat = Store.state.chat;
      if (!chat) return;
      const input = d.getElementById(`${ID}-chat-in`);
      const txt = input.value.trim();
      if (!txt) return;
      const key = `c-${chat.id}`;
      let msgs = Storage.get(key, []);
      msgs.push({ s: 1, t: txt, id: Date.now() });
      if (msgs.length > 100) msgs = msgs.slice(-100);
      Storage.set(key, msgs);
      sendMsg(`我给${chat.姓名}发送了: ${txt}`);
      const el = d.getElementById(`${ID}-chat-msgs`);
      el.innerHTML += `<div class="ps-msg sent"><div class="ps-bubble">${escapeHtml(txt)}</div></div><div class="ps-msg recv" id="${ID}-typing"><div class="ps-bubble"><span class="ps-spinner" style="width:12px;height:12px"></span></div></div>`;
      el.scrollTop = el.scrollHeight;
      input.value = "";
      input.disabled = true;
      try {
        const reply = await API.request(
          `你是${chat.姓名}（${chat.备注 || "漫展认识的人"}），对方说："${txt}"。简短回复15-40字：`, 150
        );
        d.getElementById(`${ID}-typing`)?.remove();
        const replyText = reply.trim();
        msgs.push({ s: 0, t: replyText, id: Date.now() });
        if (msgs.length > 100) msgs = msgs.slice(-100);
        Storage.set(key, msgs);
        el.innerHTML += `<div class="ps-msg recv"><div class="ps-bubble">${escapeHtml(replyText)}</div></div>`;
        el.scrollTop = el.scrollHeight;
      } catch {
        d.getElementById(`${ID}-typing`)?.remove();
        el.innerHTML += '<div class="ps-msg recv"><div class="ps-bubble">（消息发送失败）</div></div>';
      }
      input.disabled = false;
      input.focus();
    }

    // ── 地图 ──
    function renderMap(d) {
      try {
        const gs = GameState.get();
        const cur = gs.系统?.当前地点 || "未知";
        const curV = cur.split("-")[0];
        let h = `<div class="ps-map"><div class="ps-map-cur"><div class="ps-map-cur-lbl">📍 当前位置</div><div class="ps-map-cur-loc">${escapeHtml(cur)}</div></div>`;
        Object.entries(VENUES).forEach(([name, v]) => {
          const isCur = curV === name;
          h += `<div class="ps-venue ${isCur ? "cur exp" : ""}" data-v="${escapeHtml(name)}"><div class="ps-venue-hdr"><span class="ps-venue-icon">${v.icon}</span><span class="ps-venue-name">${escapeHtml(name)}</span><span class="ps-venue-arrow">▼</span></div><div class="ps-areas"><div style="font-size:10px;color:var(--muted);margin-bottom:12px">${escapeHtml(v.desc)}</div>`;
          Object.entries(v.areas).forEach(([floor, areas]) => {
            const hid = floor === "隐蔽区域";
            h += `<div class="ps-floor"><div class="ps-floor-name">${hid ? "🔒 " : ""}${escapeHtml(floor)}</div><div class="ps-area-grid">`;
            areas.forEach((a) => {
              const full = `${name}-${a}`;
              h += `<div class="ps-area ${cur === full ? "cur" : ""} ${hid ? "hid" : ""}" data-loc="${escapeHtml(full)}">${escapeHtml(a)}</div>`;
            });
            h += "</div></div>";
          });
          h += "</div></div>";
        });
        h += "</div>";
        const el = d.getElementById(`${ID}-map-list`);
        el.innerHTML = h;
        el.querySelectorAll(".ps-venue-hdr").forEach((e) => {
          e.onclick = () => e.closest(".ps-venue").classList.toggle("exp");
        });
        el.querySelectorAll(".ps-area").forEach((e) => {
          e.onclick = () => {
            sendMsg(`[系统] 移动到了「${e.dataset.loc}」`);
            toast(d, `已移动到 ${e.dataset.loc}`, "ok");
            Notify.add("🗺️", `移动到了「${e.dataset.loc}」`);
          };
        });
      } catch (err) { toast(d, `地图加载出错：${err.message}`, "err"); }
    }

    // ── 通知页 ──
    function renderNotify(d) {
      const el = d.getElementById(`${ID}-notify-list`);
      const list = Notify.list;
      let h = `<div class="ps-notify-actions"><button class="ps-notify-act read" id="${ID}-notify-read">✅ 全部已读</button><button class="ps-notify-act clear" id="${ID}-notify-clear">🗑️ 清空</button></div>`;
      if (!list.length) {
        h += emptyState("🔔", "暂无通知");
      } else {
        list.forEach((n) => {
          h += `<div class="ps-notify-item ${n.read ? "" : "unread"}"><span class="ps-notify-icon">${n.icon}</span><span class="ps-notify-text">${escapeHtml(n.text)}</span><span class="ps-notify-time">${escapeHtml(n.time)}</span></div>`;
        });
      }
      el.innerHTML = h;
      d.getElementById(`${ID}-notify-read`).onclick = () => { Notify.markAllRead(); renderNotify(d); };
      d.getElementById(`${ID}-notify-clear`).onclick = () => { Notify.clear(); renderNotify(d); };
    }

    // ── 主题管理 ──
    async function renderTheme(d) {
      const el = d.getElementById(`${ID}-theme-list`);
      el.innerHTML = loadingState("读取主题状态...");
      try {
        await TGT.initWorldbook();
        if (!TGT.worldBookName) {
          el.innerHTML = emptyState("📖", "未找到世界书", "请确保角色卡已加载且包含世界书");
          return;
        }
        const themeIcons = { "明日方舟cos主题": "⚔️", "碧蓝航线主题": "⚓", "nikkie主题": "💎", "米哈游游戏主题": "🌟", "自定义游戏主题": "🎮" };
        for (const themeName of TGT.THEME_NAMES) {
          Store.state.themeStatus[themeName] = await TGT.getEntryStatus(TGT.THEME_MAP[themeName]);
        }
        const enabledCount = Object.values(Store.state.themeStatus).filter((v) => v === true).length;
        let h = `<div class="ps-theme-header"><div class="ps-theme-header-title">🎭 TGT 主题控制器</div><div class="ps-theme-header-desc">${enabledCount} / ${TGT.THEME_NAMES.length} 个主题已启用</div></div>`;
        h += `<div class="ps-theme-always"><div class="ps-theme-always-info">📋 总览 <span class="ps-theme-always-badge">常驻</span></div><span class="ps-theme-status on">✅ 始终启用</span></div>`;
        h += '<div class="ps-theme-list">';
        for (const themeName of TGT.THEME_NAMES) {
          const isOn = Store.state.themeStatus[themeName] === true;
          const icon = themeIcons[themeName] || "🎭";
          const entryName = TGT.THEME_MAP[themeName];
          h += `<div class="ps-theme-item ${isOn ? "enabled" : ""}" data-theme="${escapeHtml(themeName)}"><div class="ps-theme-info"><div class="ps-theme-name">${icon} ${escapeHtml(themeName)}</div><div class="ps-theme-entry">条目: ${escapeHtml(entryName)}</div></div><span class="ps-theme-status ${isOn ? "on" : "off"}" data-theme-label="${escapeHtml(themeName)}">${isOn ? "✅ 启用" : "❌ 关闭"}</span><button class="ps-theme-toggle ${isOn ? "on" : "off"}" data-theme-toggle="${escapeHtml(themeName)}"></button></div>`;
        }
        h += "</div>";
        h += `<div class="ps-theme-actions"><button class="ps-theme-act-btn enable-all" id="${ID}-theme-enable-all">🔓 全部启用</button><button class="ps-theme-act-btn disable-all" id="${ID}-theme-disable-all">🔒 全部关闭</button></div>`;
        el.innerHTML = h;

        el.querySelectorAll("[data-theme-toggle]").forEach((btn) => {
          btn.onclick = async (e) => {
            e.stopPropagation();
            const tn = btn.dataset.themeToggle;
            const entryName = TGT.THEME_MAP[tn];
            const curStatus = Store.state.themeStatus[tn];
            const newStatus = !curStatus;
            btn.className = `ps-theme-toggle ${newStatus ? "on" : "off"}`;
            const label = d.querySelector(`[data-theme-label="${tn}"]`);
            if (label) { label.className = `ps-theme-status ${newStatus ? "on" : "off"}`; label.textContent = newStatus ? "✅ 启用" : "❌ 关闭"; }
            const item = btn.closest(".ps-theme-item");
            if (item) item.classList.toggle("enabled", newStatus);
            const success = await TGT.setEntry(entryName, newStatus);
            if (success) {
              Store.state.themeStatus[tn] = newStatus;
              toast(d, `${tn}: ${newStatus ? "✅ 已启用" : "❌ 已关闭"}`, "ok");
              Notify.add("🎭", `${tn} ${newStatus ? "已启用" : "已关闭"}`);
              const cnt = Object.values(Store.state.themeStatus).filter((v) => v === true).length;
              const hd = el.querySelector(".ps-theme-header-desc");
              if (hd) hd.textContent = `${cnt} / ${TGT.THEME_NAMES.length} 个主题已启用`;
            } else {
              btn.className = `ps-theme-toggle ${curStatus ? "on" : "off"}`;
              if (label) { label.className = `ps-theme-status ${curStatus ? "on" : "off"}`; label.textContent = curStatus ? "✅ 启用" : "❌ 关闭"; }
              if (item) item.classList.toggle("enabled", curStatus);
              toast(d, `切换失败: 未找到条目「${entryName}」`, "err");
            }
          };
        });

        d.getElementById(`${ID}-theme-enable-all`).onclick = async () => {
          toast(d, "正在启用所有主题...", "");
          let sc = 0;
          for (const tn of TGT.THEME_NAMES) { if (await TGT.setEntry(TGT.THEME_MAP[tn], true)) { Store.state.themeStatus[tn] = true; sc++; } }
          toast(d, `✅ 已启用 ${sc} 个主题`, "ok");
          Notify.add("🎭", `批量启用了 ${sc} 个主题`);
          renderTheme(d);
        };
                d.getElementById(`${ID}-theme-disable-all`).onclick = async () => {
          toast(d, "正在关闭所有主题...", "");
          let sc = 0;
          for (const tn of TGT.THEME_NAMES) {
            if (await TGT.setEntry(TGT.THEME_MAP[tn], false)) { Store.state.themeStatus[tn] = false; sc++; }
          }
          toast(d, `❌ 已关闭 ${sc} 个主题`, "ok");
          Notify.add("🎭", `批量关闭了 ${sc} 个主题`);
          renderTheme(d);
        };
      } catch (err) {
        el.innerHTML = errorState(err.message);
      }
    }

    // ── 主页小组件 ──
    function renderWidgets(d) {
      const gs = GameState.get();
      const el = d.getElementById(`${ID}-widgets`);
      if (!el) return;
      const widgets = Store.state.config.widgets || [];
      let h = "";

      if (widgets.includes("tasks")) {
        const active = Object.entries(gs.任务?.进行中任务 || {});
        if (active.length) {
          h += '<div class="ps-widget" data-widget-app="task"><div class="ps-widget-title">📋 进行中任务</div><div class="ps-widget-content">';
          active.slice(0, 3).forEach(([id, t]) => {
            h += `<div class="ps-widget-task-item"><span class="ps-widget-task-name">🔥 ${escapeHtml(t.名称 || "未知")}</span><span class="ps-widget-task-reward">💰${escapeHtml(String(t.奖励 || "?"))}</span></div>`;
          });
          if (active.length > 3) h += `<div style="font-size:10px;color:var(--muted);margin-top:4px">还有 ${active.length - 3} 个任务...</div>`;
          h += "</div></div>";
        }
      }

      if (widgets.includes("contacts")) {
        const contactIds = Object.keys(gs.联系人 || {});
        if (contactIds.length) {
          h += '<div class="ps-widget" data-widget-app="contact"><div class="ps-widget-title">👥 最近联系人</div><div class="ps-widget-content"><div class="ps-widget-contact-row">';
          contactIds.slice(0, 5).forEach((id, i) => {
            const c = gs.联系人[id];
            h += `<div class="ps-widget-contact-chip"><div class="ps-widget-contact-dot" style="background:${PALETTE[i % PALETTE.length]}"></div>${escapeHtml(c.姓名 || id)}</div>`;
          });
          if (contactIds.length > 5) h += `<div class="ps-widget-contact-chip">+${contactIds.length - 5}</div>`;
          h += "</div></div></div>";
        }
      }

      if (widgets.includes("location")) {
        const loc = gs.系统?.当前地点 || "未知";
        h += `<div class="ps-widget" data-widget-app="map"><div class="ps-widget-title">📍 当前位置</div><div class="ps-widget-content"><div class="ps-widget-loc">🗺️ ${escapeHtml(loc)}</div></div></div>`;
      }

      if (widgets.includes("coser")) {
        const coserList = gs.Coser列表 || gs["Coser列表"] || {};
        const entries = Object.entries(coserList);
        if (entries.length) {
          const colors = ["#FF6B9D","#6C5CE7","#00B894","#FDCB6E","#E17055"];
          h += '<div class="ps-widget" data-widget-app="coserinfo"><div class="ps-widget-title">💃 遭遇Coser · ' + entries.length + '位</div><div class="ps-widget-content"><div class="ps-widget-coser-row">';
          entries.slice(0, 4).forEach(([cn, coser], i) => {
            const name = escapeHtml(coser.姓名 || cn);
            const favor = parseInt(coser.好感度) || 0;
            h += `<div class="ps-widget-coser-chip" style="border-color:${colors[i % colors.length]}30"><span style="color:${colors[i % colors.length]}">${name[0]}</span> ${name} <span style="font-size:9px;color:var(--muted)">❤${favor}</span></div>`;
          });
          if (entries.length > 4) h += `<div class="ps-widget-coser-chip">+${entries.length - 4}</div>`;
          h += "</div></div></div>";
        }
      }

      if (widgets.includes("bag")) {
        const items = parseBagItems(gs);
        if (items.length) {
          const totalCount = items.reduce((sum, item) => sum + item.count, 0);
          h += '<div class="ps-widget" data-widget-app="bag"><div class="ps-widget-title">🎒 背包 · ' + items.length + '种 · ' + totalCount + '件</div><div class="ps-widget-content"><div class="ps-widget-bag-row">';
          items.slice(0, 4).forEach((item) => {
            const icon = getBagIcon(item.type, item.name);
            h += `<div class="ps-widget-bag-chip">${icon} ${escapeHtml(item.name)} ×${item.count}</div>`;
          });
          if (items.length > 4) h += `<div class="ps-widget-bag-chip">+${items.length - 4}</div>`;
          h += "</div></div></div>";
        }
      }

      el.innerHTML = h;
      el.querySelectorAll("[data-widget-app]").forEach((w) => {
        w.onclick = () => Router.navigate(w.dataset.widgetApp);
      });
    }

    // ── 设置 ──
    function renderSet(d) {
      const c = Store.state.config;
      const widgetOptions = [
        { key: "tasks", label: "📋 任务" },
        { key: "contacts", label: "👥 联系人" },
        { key: "location", label: "📍 位置" },
        { key: "coser", label: "💃 Coser" },
        { key: "bag", label: "🎒 背包" },
      ];
      d.getElementById(`${ID}-set-form`).innerHTML = `<div class="ps-set">
        <div class="ps-set-grp"><label class="ps-set-lbl">API 地址</label><input class="ps-input" id="${ID}-api-url" placeholder="https://api.example.com/v1" value="${escapeHtml(c.apiUrl)}"></div>
        <div class="ps-set-grp"><label class="ps-set-lbl">API 密钥</label><input class="ps-input" type="password" id="${ID}-api-key" placeholder="sk-..." value="${escapeHtml(c.apiKey)}"></div>
        <div class="ps-set-grp"><label class="ps-set-lbl">模型</label><div style="display:flex;gap:6px"><select class="ps-input" id="${ID}-model" style="flex:1">${c.model ? `<option value="${escapeHtml(c.model)}">${escapeHtml(c.model)}</option>` : '<option value="">请获取</option>'}</select><button class="ps-btn ps-btn-s" style="flex:0 0 auto;padding:0 14px" id="${ID}-fetch">获取</button></div></div>
        <div class="ps-set-grp"><label class="ps-set-lbl">玩家名称</label><input class="ps-input" id="${ID}-pname" value="${escapeHtml(c.playerName)}"></div>
        <div class="ps-set-grp">
          <label class="ps-set-lbl">🎨 配色方案</label>
          <div class="ps-scheme-btns">
            <button class="ps-scheme-btn dark-btn ${c.colorScheme !== "light" ? "active" : ""}" data-scheme="dark">🌙 深色</button>
            <button class="ps-scheme-btn light-btn ${c.colorScheme === "light" ? "active" : ""}" data-scheme="light">☀️ 浅色</button>
          </div>
        </div>
        <div class="ps-set-grp">
          <label class="ps-set-lbl">📐 显示分辨率</label>
          <div style="display:flex;gap:8px">
            ${RES_ORDER.map((key) => {
              const p = RES_PRESETS[key];
              return `<button class="ps-btn ${Store.state.resolution === key ? "ps-btn-p" : "ps-btn-s"}" style="flex:1;padding:10px 6px;font-size:11px" data-res="${key}">${p.label} ${p.name}<br><span style="font-size:9px;opacity:.7">${p.width}×${p.height}</span></button>`;
            }).join("")}
          </div>
        </div>
        <div class="ps-set-grp">
          <label class="ps-set-lbl">🧩 主页小组件</label>
          <div class="ps-widget-cfg">
            ${widgetOptions.map((w) => `<div class="ps-widget-chk ${(c.widgets || []).includes(w.key) ? "on" : ""}" data-wkey="${w.key}"><div class="ps-widget-chk-dot">${(c.widgets || []).includes(w.key) ? "✓" : ""}</div>${w.label}</div>`).join("")}
          </div>
        </div>
        <div class="ps-set-grp">
          <label class="ps-set-lbl">🖼️ 壁纸</label>
          <div class="ps-wp-preview" id="${ID}-wp-preview">${c.wallpaper ? `<img src="${c.wallpaper}" alt="壁纸">` : '<span class="ps-wp-placeholder">未设置壁纸</span>'}</div>
          <input type="file" accept="image/*" class="ps-wp-file" id="${ID}-wp-file">
          <div class="ps-wp-btns"><button class="ps-wp-btn upload" id="${ID}-wp-upload">📁 选择图片</button><button class="ps-wp-btn clear" id="${ID}-wp-clear">🗑️ 清除壁纸</button></div>
        </div>
        <div class="ps-btns"><button class="ps-btn ps-btn-p" id="${ID}-save">💾 保存设置</button><button class="ps-btn ps-btn-s" id="${ID}-test">🔗 测试API</button></div>
        <div style="margin-top:20px;padding:10px;background:rgba(255,255,255,.05);border-radius:10px;font-size:11px;color:var(--muted)">
          <div style="margin-bottom:8px">📊 调试信息</div>
          <div id="${ID}-debug"></div>
        </div>
      </div>`;

      // 配色切换
      d.querySelectorAll("[data-scheme]").forEach((btn) => {
        btn.onclick = () => {
          c.colorScheme = btn.dataset.scheme;
          d.querySelectorAll("[data-scheme]").forEach((b) => b.classList.toggle("active", b.dataset.scheme === c.colorScheme));
          UI.applyColorScheme(d);
        };
      });

      // 分辨率
      d.querySelectorAll("[data-res]").forEach((btn) => {
        btn.onclick = () => {
          Store.set("resolution", btn.dataset.res);
          Storage.remove("phone-pos");
          Storage.setRaw("res", Store.state.resolution);
          UI.applyContainerStyles(d);
          d.querySelectorAll("[data-res]").forEach((b) => {
            b.className = `ps-btn ${b.dataset.res === Store.state.resolution ? "ps-btn-p" : "ps-btn-s"}`;
            b.style.cssText = "flex:1;padding:10px 6px;font-size:11px";
          });
          toast(d, `已切换至${RES_PRESETS[Store.state.resolution].name}模式`, "ok");
        };
      });

      // Widget配置
      d.querySelectorAll(".ps-widget-chk").forEach((chk) => {
        chk.onclick = () => {
          const key = chk.dataset.wkey;
          if (!c.widgets) c.widgets = ["tasks", "contacts", "location"];
          const idx = c.widgets.indexOf(key);
          if (idx >= 0) c.widgets.splice(idx, 1); else c.widgets.push(key);
          chk.classList.toggle("on");
          chk.querySelector(".ps-widget-chk-dot").textContent = chk.classList.contains("on") ? "✓" : "";
        };
      });

      // 调试信息
      try {
        const gs = GameState.get();
        const scale = calculateOptimalScale();
        const coserCount = Object.keys(gs.Coser列表 || gs["Coser列表"] || {}).length;
        const curRes = RES_PRESETS[Store.state.resolution] || RES_PRESETS.phone;
        d.getElementById(`${ID}-debug`).innerHTML = `
          <div>MVU: ${GameState.getMvuData() ? "✅" : "❌"} | 金钱: ${gs.主角?.金钱 ?? "N/A"} | 联系人: ${Object.keys(gs.联系人 || {}).length}</div>
          <div>背包: ${gs.主角?.物品栏 ? Object.keys(gs.主角.物品栏).length : 0}种 | Coser: ${coserCount} | 世界书: ${TGT.worldBookName || "未初始化"}</div>
          <div>分辨率: ${curRes.label}${curRes.width}×${curRes.height} | 缩放: ${scale.toFixed(2)} | ${isMobile() ? "📱移动端" : "💻桌面端"}</div>
          <div>屏幕: ${(window.top || window).innerWidth}×${(window.top || window).innerHeight} | 通知: ${Notify.unread}条未读</div>`;
      } catch {}

      // 壁纸上传
      d.getElementById(`${ID}-wp-upload`).onclick = () => d.getElementById(`${ID}-wp-file`).click();
      d.getElementById(`${ID}-wp-file`).onchange = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        if (file.size > 2 * 1024 * 1024) { toast(d, "图片太大，请选择2MB以内", "err"); return; }
        if (!file.type.startsWith("image/")) { toast(d, "请选择图片文件", "err"); return; }
        const reader = new FileReader();
        reader.onload = (ev) => {
          const img = new Image();
          img.onload = () => {
            try {
              const canvas = document.createElement("canvas");
              let w = img.width, h = img.height;
              if (w > 720) { h = (h * 720) / w; w = 720; }
              if (h > 1280) { w = (w * 1280) / h; h = 1280; }
              canvas.width = w; canvas.height = h;
              canvas.getContext("2d").drawImage(img, 0, 0, w, h);
              c.wallpaper = canvas.toDataURL("image/jpeg", 0.7);
              d.getElementById(`${ID}-wp-preview`).innerHTML = `<img src="${c.wallpaper}" alt="壁纸">`;
              toast(d, "壁纸已选择，点击保存生效", "ok");
            } catch { toast(d, "图片处理失败", "err"); }
          };
          img.src = ev.target.result;
        };
        reader.readAsDataURL(file);
      };
      d.getElementById(`${ID}-wp-clear`).onclick = () => {
        c.wallpaper = "";
        d.getElementById(`${ID}-wp-preview`).innerHTML = '<span class="ps-wp-placeholder">未设置壁纸</span>';
        UI.applyWallpaper(d);
        toast(d, "壁纸已清除", "ok");
        Store.saveConfig();
      };

      // 获取模型
      d.getElementById(`${ID}-fetch`).onclick = async () => {
        const url = d.getElementById(`${ID}-api-url`).value.trim();
        const key = d.getElementById(`${ID}-api-key`).value.trim();
        if (!url) { toast(d, "请先填写API地址", "err"); return; }
        try {
          const models = await API.fetchModels(url, key);
          d.getElementById(`${ID}-model`).innerHTML = models.length
            ? models.map((m) => `<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`).join("")
            : '<option value="">未找到模型</option>';
          toast(d, `找到 ${models.length} 个模型`, "ok");
        } catch (e) { toast(d, `获取模型失败：${e.message}`, "err"); }
      };

      // 保存设置
      d.getElementById(`${ID}-save`).onclick = () => {
        try {
          c.apiUrl = d.getElementById(`${ID}-api-url`).value.trim();
          c.apiKey = d.getElementById(`${ID}-api-key`).value.trim();
          c.model = d.getElementById(`${ID}-model`).value;
          c.playerName = d.getElementById(`${ID}-pname`).value.trim() || "玩家";
          Store.saveConfig();
          UI.applyWallpaper(d);
          UI.applyColorScheme(d);
          renderWidgets(d);
          toast(d, "设置已保存 ✓", "ok");
        } catch (e) { toast(d, `保存失败：${e.message}`, "err"); }
      };

      // 测试API
      d.getElementById(`${ID}-test`).onclick = async () => {
        try {
          c.apiUrl = d.getElementById(`${ID}-api-url`).value.trim();
          c.apiKey = d.getElementById(`${ID}-api-key`).value.trim();
          c.model = d.getElementById(`${ID}-model`).value;
          if (!c.apiUrl) { toast(d, "请填写API地址", "err"); return; }
          if (!c.model) { toast(d, "请选择模型", "err"); return; }
          toast(d, "正在测试连接...", "");
          await API.request("测试，回复OK", 50);
          toast(d, "API连接成功！✓", "ok");
        } catch (e) { toast(d, `API测试失败：${e.message}`, "err"); }
      };
    }

    // ── Pages模块返回 ──
    return {
      loadForum, renderForum, loadShop, renderShop,
      loadTask, renderTask, renderBag, openRecruitPopup,
      renderCoserInfo, renderContact, renderMsgList,
      openChat, sendChat, renderMap, renderNotify,
      renderTheme, renderWidgets, renderSet,
    };
  })();

