  // ═══════════════════════════════════════════════════════════════
  //  模块12: 清理与卸载
  // ═══════════════════════════════════════════════════════════════
  function cleanupOldInstances(d) {
    d.querySelectorAll(`[id^="${ID}-"]`).forEach((e) => e.remove());
    d.querySelectorAll(".ps-toast").forEach((e) => e.remove());
    d.querySelectorAll(".ps-confirm").forEach((e) => e.remove());
    d.querySelectorAll(".ps-longpress-menu").forEach((e) => e.remove());
    d.querySelectorAll(".ps-recruit-overlay").forEach((e) => e.remove());
  }

  function unloadPsUI() {
    try {
      const d = window.top ? window.top.document : document;
      cleanupOldInstances(d);
      const w = window.top || window;
      delete w.psDashboard;
      delete w.psUnload;
    } catch {}
    window.removeEventListener("pagehide", unloadPsUI);
  }

  // ═══════════════════════════════════════════════════════════════
  //  模块13: 初始化主入口
  // ═══════════════════════════════════════════════════════════════
  function init() {
    try {
      const d = window.top ? window.top.document : document;
      const w = window.top || window;

      window.removeEventListener("pagehide", unloadPsUI);
      cleanupOldInstances(d);

      d.head.insertAdjacentHTML("beforeend", CSS);
      d.body.insertAdjacentHTML("beforeend", HTML);

      Store.loadConfig();
      Notify.init();
      Router.init(d);

      // 注册页面钩子
      Router.register("forum", (d) => {
        const cat = Store.state.forum.cat;
        if (!Store.state.forum.posts[cat].length) Pages.loadForum(d, cat);
        else Pages.renderForum(d, cat);
      });
      Router.register("shop", (d) => {
        const cat = Store.state.shop.cat;
        if (!Store.state.shop.items[cat].length) Pages.loadShop(d, cat);
        else Pages.renderShop(d, cat);
      });
      Router.register("task", (d) => {
        const cat = Store.state.task.cat;
        if (!Store.state.task.list[cat].length) Pages.loadTask(d, cat);
        else Pages.renderTask(d, cat);
      });
      Router.register("bag", (d) => Pages.renderBag(d));
      Router.register("coserinfo", (d) => Pages.renderCoserInfo(d));
      Router.register("contact", (d) => Pages.renderContact(d));
      Router.register("msglist", (d) => Pages.renderMsgList(d));
      Router.register("map", (d) => Pages.renderMap(d));
      Router.register("notify", (d) => { Pages.renderNotify(d); Notify.markAllRead(); });
      Router.register("theme", (d) => Pages.renderTheme(d));
      Router.register("set", (d) => Pages.renderSet(d));

      // ── 响应式 Store watch 接入 ──
      Store.watch("forum.posts", () => {
        if (Router.current === "forum") Pages.renderForum(d, Store.state.forum.cat);
      });
      Store.watch("shop.items", () => {
        if (Router.current === "shop") Pages.renderShop(d, Store.state.shop.cat);
      });
      Store.watch("task.list", () => {
        if (Router.current === "task") Pages.renderTask(d, Store.state.task.cat);
      });

      const btn = d.getElementById(`${ID}-btn`);
      const overlay = d.getElementById(`${ID}-overlay`);

      UI.applyWallpaper(d);
      UI.applyColorScheme(d);
      UI.applyContainerStyles(d);

      // resize
      w.addEventListener("resize", () => {
        refreshMobileCache();
        if (isMobile()) Storage.remove("phone-pos");
        if (overlay.classList.contains("show")) UI.applyContainerStyles(d);
      });

      // 悬浮球位置
      const savedPos = Storage.get("pos");
      if (savedPos) {
        const sw = w.innerWidth, sh = w.innerHeight;
        btn.style.left = Math.max(0, Math.min(savedPos.x, sw - 52)) + "px";
        btn.style.top = Math.max(0, Math.min(savedPos.y, sh - 52)) + "px";
        btn.style.right = "auto";
        btn.style.bottom = "auto";
      } else {
        centerBtn();
      }
      function centerBtn() {
        setTimeout(() => {
          const sw = w.innerWidth || document.documentElement.clientWidth;
          const sh = w.innerHeight || document.documentElement.clientHeight;
          btn.style.right = "auto";
          btn.style.bottom = "auto";
          btn.style.setProperty("left", (sw / 2 - 26) + "px", "important");
          btn.style.setProperty("top", (sh / 2 - 26) + "px", "important");
        }, 100);
      }

      UI.initBtnDrag(btn, d);
      UI.initPhoneDrag(d);

      // 关闭按钮
      const closeBtn = d.getElementById(`${ID}-close-btn`);
      const preventDrag = (e) => { e.stopPropagation(); e.stopImmediatePropagation(); };
      closeBtn.addEventListener("pointerdown", preventDrag, true);
      closeBtn.addEventListener("pointerup", preventDrag, true);
      closeBtn.addEventListener("click", (e) => { preventDrag(e); e.preventDefault(); Router.closePhone(); }, true);
      closeBtn.addEventListener("touchend", (e) => { preventDrag(e); e.preventDefault(); Router.closePhone(); }, { capture: true, passive: false });

      // 分辨率按钮
      const resBtn = d.getElementById(`${ID}-res-btn`);
      resBtn.addEventListener("pointerdown", preventDrag, true);
      resBtn.addEventListener("pointerup", preventDrag, true);
      resBtn.addEventListener("click", (e) => { preventDrag(e); e.preventDefault(); UI.cycleResolution(d); }, true);
      resBtn.addEventListener("touchend", (e) => { preventDrag(e); e.preventDefault(); UI.cycleResolution(d); }, { capture: true, passive: false });

      // 通知铃铛
      const notifyWrap = d.getElementById(`${ID}-notify-wrap`);
      notifyWrap.addEventListener("pointerdown", preventDrag, true);
      notifyWrap.addEventListener("pointerup", preventDrag, true);
      notifyWrap.addEventListener("click", (e) => { preventDrag(e); e.preventDefault(); Router.navigate("notify"); }, true);

      // 点击遮罩关闭
      overlay.addEventListener("click", (e) => { if (e.target === overlay) Router.closePhone(); });

      // 导航绑定
      d.querySelectorAll(".ps-app").forEach((a) => (a.onclick = () => Router.navigate(a.dataset.app)));
      d.querySelectorAll("[data-back]").forEach((b) => (b.onclick = () => Router.back()));
      d.querySelectorAll(".ps-nav-item").forEach((n) => {
        n.onclick = () => n.dataset.nav === "home" ? Router.goHome() : Router.navigate(n.dataset.nav);
      });

      // 论坛tab
      d.querySelectorAll(`#${ID}-forum .ps-tab`).forEach((t) => {
        t.onclick = () => {
          d.querySelectorAll(`#${ID}-forum .ps-tab`).forEach((x) => x.classList.remove("on"));
          t.classList.add("on");
          Store.state.forum.cat = t.dataset.cat;
          if (!Store.state.forum.posts[Store.state.forum.cat].length) Pages.loadForum(d, Store.state.forum.cat);
          else Pages.renderForum(d, Store.state.forum.cat);
        };
      });
      d.getElementById(`${ID}-forum-ref`).onclick = () => Pages.loadForum(d, Store.state.forum.cat);

      // 商城tab
      d.querySelectorAll(`#${ID}-shop .ps-tab`).forEach((t) => {
        t.onclick = () => {
          d.querySelectorAll(`#${ID}-shop .ps-tab`).forEach((x) => x.classList.remove("on"));
          t.classList.add("on");
          Store.state.shop.cat = t.dataset.cat;
          if (!Store.state.shop.items[Store.state.shop.cat].length) Pages.loadShop(d, Store.state.shop.cat);
          else Pages.renderShop(d, Store.state.shop.cat);
        };
      });
      d.getElementById(`${ID}-shop-ref`).onclick = () => Pages.loadShop(d, Store.state.shop.cat);

      // 任务tab
      d.querySelectorAll(`#${ID}-task .ps-tab`).forEach((t) => {
        t.onclick = () => {
          d.querySelectorAll(`#${ID}-task .ps-tab`).forEach((x) => x.classList.remove("on"));
          t.classList.add("on");
          Store.state.task.cat = t.dataset.cat;
          if (!Store.state.task.list[Store.state.task.cat].length) Pages.loadTask(d, Store.state.task.cat);
          else Pages.renderTask(d, Store.state.task.cat);
        };
      });
      d.getElementById(`${ID}-task-ref`).onclick = () => Pages.loadTask(d, Store.state.task.cat);

      // 主题刷新
      d.getElementById(`${ID}-theme-ref`).onclick = () => Pages.renderTheme(d);

      // 聊天返回
      d.getElementById(`${ID}-chat-back`).onclick = () => {
        d.getElementById(`${ID}-chat-page`).classList.remove("on");
        const hist = Router.history;
        if (hist.length && hist[hist.length - 1] === "msglist") {
          d.getElementById(`${ID}-msglist`).classList.add("on");
          Pages.renderMsgList(d);
        } else if (hist.length && hist[hist.length - 1] === "contact") {
          d.getElementById(`${ID}-contact`).classList.add("on");
        } else {
          d.getElementById(`${ID}-msglist`).classList.add("on");
          Pages.renderMsgList(d);
        }
        Store.set("chat", null);
      };
      d.getElementById(`${ID}-chat-send`).onclick = () => Pages.sendChat(d);
      d.getElementById(`${ID}-chat-in`).onkeypress = (e) => { if (e.key === "Enter") Pages.sendChat(d); };

      // 下拉刷新
      const forumList = d.getElementById(`${ID}-forum-list`);
      const shopList = d.getElementById(`${ID}-shop-list`);
      const taskList = d.getElementById(`${ID}-task-list`);
      if (forumList) initPullToRefresh(forumList, () => Pages.loadForum(d, Store.state.forum.cat));
      if (shopList) initPullToRefresh(shopList, () => Pages.loadShop(d, Store.state.shop.cat));
      if (taskList) initPullToRefresh(taskList, () => Pages.loadTask(d, Store.state.task.cat));

      // 生命周期
      window.removeEventListener("pagehide", unloadPsUI);
      window.addEventListener("pagehide", unloadPsUI);
      w.psUnload = unloadPsUI;

      UI.updateHome(d);

      // TGT世界书初始化
      setTimeout(async () => {
        try {
          await TGT.initWorldbook();
          await TGT.setEntry(TGT.ALWAYS_ENABLED, true);
          console.log("[PS-TGT] 总览已启用");
        } catch (e) { console.log("[PS-TGT] 初始化出错:", e); }
      }, 2000);

      console.log(`✅ 紫雀 v${VERSION} 已加载（全优化版）`);
    } catch (e) {
      console.error("[PS] 初始化失败:", e);
    }
  }

  setTimeout(init, 500);
})();
